insert into public.learning_methods(id,data) values('retrieval','{"id":"retrieval","name":"Recuperación activa","evidence":"ALTA","description":"Traer una idea a la memoria antes de consultar.","steps":["Elegí una pregunta concreta.","Cerrá el material y respondé sin mirar.","Compará, corregí y volvé a intentarlo."],"category":"Aprendizaje","objective":"Traer una idea a la memoria antes de consultar.","when":"Cuando necesitás comprender, recordar o revisar un tema.","avoid":"No lo uses como único recurso ni como prueba automática de dominio.","duration":10,"subjects":["Todas"],"age":"Secundaria","example":"Sin mirar el apunte, explicá qué cambia en una reacción química.","prompt":"Enseñá Recuperación activa con una pregunta por vez. Pedí un intento y ofrecé feedback. No resuelvas una entrega escolar.","evidence_note":"La categoría corresponde a la técnica subyacente, no a una validación clínica de esta app. Revisión pedagógica pendiente."}'::jsonb) on conflict(id) do update set data=excluded.data;
insert into public.learning_methods(id,data) values('practice-testing','{"id":"practice-testing","name":"Práctica de examen","evidence":"ALTA","description":"Ensayar preguntas representativas con devolución.","steps":["Elegí temas y un tiempo posible.","Respondé antes de ver soluciones.","Analizá errores y repetí otro ejemplo."],"category":"Aprendizaje","objective":"Ensayar preguntas representativas con devolución.","when":"Cuando necesitás comprender, recordar o revisar un tema.","avoid":"No lo uses como único recurso ni como prueba automática de dominio.","duration":10,"subjects":["Todas"],"age":"Secundaria","example":"Elegí una idea del tema actual y aplicá los pasos; después comprobá con el material.","prompt":"Enseñá Práctica de examen con una pregunta por vez. Pedí un intento y ofrecé feedback. No resuelvas una entrega escolar.","evidence_note":"La categoría corresponde a la técnica subyacente, no a una validación clínica de esta app. Revisión pedagógica pendiente."}'::jsonb) on conflict(id) do update set data=excluded.data;
insert into public.learning_methods(id,data) values('spaced-practice','{"id":"spaced-practice","name":"Práctica espaciada","evidence":"ALTA","description":"Distribuir el estudio en encuentros separados.","steps":["Dividí el tema.","Reservá encuentros en varios días.","Revisá lo que cuesta más en el siguiente encuentro."],"category":"Aprendizaje","objective":"Distribuir el estudio en encuentros separados.","when":"Cuando necesitás comprender, recordar o revisar un tema.","avoid":"No lo uses como único recurso ni como prueba automática de dominio.","duration":10,"subjects":["Todas"],"age":"Secundaria","example":"Elegí una idea del tema actual y aplicá los pasos; después comprobá con el material.","prompt":"Enseñá Práctica espaciada con una pregunta por vez. Pedí un intento y ofrecé feedback. No resuelvas una entrega escolar.","evidence_note":"La categoría corresponde a la técnica subyacente, no a una validación clínica de esta app. Revisión pedagógica pendiente."}'::jsonb) on conflict(id) do update set data=excluded.data;
