insert into public.learning_methods(id,data) values('self-explanation','{"id":"self-explanation","name":"Autoexplicación","evidence":"MODERADA","description":"Explicar por qué funciona cada paso.","steps":["Leé un paso o una idea.","Explicá por qué tiene sentido con tus palabras.","Detectá el salto que no entendés y comprobalo."],"category":"Aprendizaje","objective":"Explicar por qué funciona cada paso.","when":"Cuando necesitás comprender, recordar o revisar un tema.","avoid":"No lo uses como único recurso ni como prueba automática de dominio.","duration":10,"subjects":["Todas"],"age":"Secundaria","example":"Elegí una idea del tema actual y aplicá los pasos; después comprobá con el material.","prompt":"Enseñá Autoexplicación con una pregunta por vez. Pedí un intento y ofrecé feedback. No resuelvas una entrega escolar.","evidence_note":"La categoría corresponde a la técnica subyacente, no a una validación clínica de esta app. Revisión pedagógica pendiente."}'::jsonb) on conflict(id) do update set data=excluded.data;
insert into public.learning_methods(id,data) values('feynman','{"id":"feynman","name":"Explicar con palabras simples","evidence":"MODERADA","description":"Una variante de autoexplicación sin jerga innecesaria.","steps":["Elegí una idea.","Explicásela a alguien que recién empieza.","Buscá y corregí lo que no pudiste explicar."],"category":"Aprendizaje","objective":"Una variante de autoexplicación sin jerga innecesaria.","when":"Cuando necesitás comprender, recordar o revisar un tema.","avoid":"No lo uses como único recurso ni como prueba automática de dominio.","duration":10,"subjects":["Todas"],"age":"Secundaria","example":"Elegí una idea del tema actual y aplicá los pasos; después comprobá con el material.","prompt":"Enseñá Explicar con palabras simples con una pregunta por vez. Pedí un intento y ofrecé feedback. No resuelvas una entrega escolar.","evidence_note":"La categoría corresponde a la técnica subyacente, no a una validación clínica de esta app. Revisión pedagógica pendiente."}'::jsonb) on conflict(id) do update set data=excluded.data;
insert into public.learning_methods(id,data) values('cornell','{"id":"cornell","name":"Notas Cornell","evidence":"ORGANIZACIÓN","description":"Organizar apuntes con preguntas y síntesis.","steps":["Anotá ideas en una columna amplia.","Escribí preguntas al costado.","Tapá los apuntes y contestá; cerrá con una síntesis."],"category":"Organización","objective":"Organizar apuntes con preguntas y síntesis.","when":"Cuando necesitás comprender, recordar o revisar un tema.","avoid":"No lo uses como único recurso ni como prueba automática de dominio.","duration":10,"subjects":["Todas"],"age":"Secundaria","example":"Elegí una idea del tema actual y aplicá los pasos; después comprobá con el material.","prompt":"Enseñá Notas Cornell con una pregunta por vez. Pedí un intento y ofrecé feedback. No resuelvas una entrega escolar.","evidence_note":"Herramienta de organización; no implica una ventaja universal de aprendizaje."}'::jsonb) on conflict(id) do update set data=excluded.data;
insert into public.learning_methods(id,data) values('pomodoro','{"id":"pomodoro","name":"Pomodoro","evidence":"ORGANIZACIÓN","description":"Hacer más fácil comenzar y descansar.","steps":["Elegí un objetivo pequeño.","Trabajá 25 minutos; podés empezar con 10.","Descansá 5 minutos y evaluá si conviene continuar."],"category":"Organización","objective":"Hacer más fácil comenzar y descansar.","when":"Cuando necesitás comprender, recordar o revisar un tema.","avoid":"No lo uses como único recurso ni como prueba automática de dominio.","duration":25,"subjects":["Todas"],"age":"Secundaria","example":"Elegí una idea del tema actual y aplicá los pasos; después comprobá con el material.","prompt":"Enseñá Pomodoro con una pregunta por vez. Pedí un intento y ofrecé feedback. No resuelvas una entrega escolar.","evidence_note":"Herramienta de organización; no implica una ventaja universal de aprendizaje."}'::jsonb) on conflict(id) do update set data=excluded.data;
insert into public.learning_methods(id,data) values('time-blocking','{"id":"time-blocking","name":"Bloques de tiempo","evidence":"ORGANIZACIÓN","description":"Reservar un lugar real para estudiar en la semana.","steps":["Marcá colegio, sueño y actividades.","Elegí un espacio disponible.","Reservá una acción concreta dejando margen."],"category":"Organización","objective":"Reservar un lugar real para estudiar en la semana.","when":"Cuando necesitás comprender, recordar o revisar un tema.","avoid":"No lo uses como único recurso ni como prueba automática de dominio.","duration":10,"subjects":["Todas"],"age":"Secundaria","example":"Elegí una idea del tema actual y aplicá los pasos; después comprobá con el material.","prompt":"Enseñá Bloques de tiempo con una pregunta por vez. Pedí un intento y ofrecé feedback. No resuelvas una entrega escolar.","evidence_note":"Herramienta de organización; no implica una ventaja universal de aprendizaje."}'::jsonb) on conflict(id) do update set data=excluded.data;
