insert into public.learning_methods(id,data) values('worked-examples','{"id":"worked-examples","name":"Ejemplos resueltos","evidence":"MODERADA","description":"Estudiar el razonamiento antes de resolver un caso nuevo.","steps":["Leé un ejemplo similar resuelto.","Explicá cada paso y su motivo.","Resolvé otro ejemplo con menos ayuda."],"category":"Aprendizaje","objective":"Estudiar el razonamiento antes de resolver un caso nuevo.","when":"Al comenzar un procedimiento nuevo.","avoid":"No lo uses como único recurso ni como prueba automática de dominio.","duration":10,"subjects":["Matemática","Física","Química"],"age":"Secundaria","example":"Elegí una idea del tema actual y aplicá los pasos; después comprobá con el material.","prompt":"Enseñá Ejemplos resueltos con una pregunta por vez. Pedí un intento y ofrecé feedback. No resuelvas una entrega escolar.","evidence_note":"La categoría corresponde a la técnica subyacente, no a una validación clínica de esta app. Revisión pedagógica pendiente."}'::jsonb) on conflict(id) do update set data=excluded.data;
